-- =============================================================================
-- 08_update_jobs_and_company_actions.sql
-- Cập nhật schema và seed dữ liệu mẫu cho job_db (job-service)
-- 1. ALTER TABLE jobs: status, reviewed_by, reviewed_at, rejected_reason
-- 2. CREATE TABLE company_actions theo entity CompanyAction.java
-- 3. Seed 10 Companies
-- 4. Seed 120 Jobs (100–150 jobs) với đủ thuộc tính mới
-- 5. Seed company_actions: LOCK, UNLOCK, APPROVE_JD, REJECT_JD với số lượng tương ứng
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =============================================================================
-- 1. ALTER TABLE jobs (thêm thuộc tính mới nếu chưa tồn tại)
-- =============================================================================
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS reviewed_by VARCHAR(100);
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS reviewed_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS rejected_reason VARCHAR(1000);

-- =============================================================================
-- 2. CREATE TABLE company_actions theo entity CompanyAction.java
-- =============================================================================
CREATE TABLE IF NOT EXISTS company_actions (
    id UUID PRIMARY KEY,
    company_id UUID NOT NULL,
    action VARCHAR(20) NOT NULL,
    target_id UUID,
    reason VARCHAR(1000),
    staff_id VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_company_actions_company ON company_actions(company_id, created_at);
CREATE INDEX IF NOT EXISTS idx_company_actions_action ON company_actions(action);
CREATE INDEX IF NOT EXISTS idx_company_actions_target ON company_actions(target_id);

-- =============================================================================
-- 3. ĐẢM BẢO 10 DOANH NGHIỆP (COMPANIES)
-- =============================================================================
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, industry = EXCLUDED.industry, size = EXCLUDED.size, status = EXCLUDED.status, updated_at = NOW();

-- =============================================================================
-- 4. ĐẢM BẢO 120 JOBS (100–150 JOBS) VỚI ĐỦ CỘT MỚI: status, reviewed_by, reviewed_at, rejected_reason
-- 84 APPROVED (70%), 12 PENDING (10%), 12 REJECTED (10%), 12 CLOSED (10%)
-- =============================================================================
ON CONFLICT (id) DO UPDATE SET
    status = EXCLUDED.status,
    reviewed_by = EXCLUDED.reviewed_by,
    reviewed_at = EXCLUDED.reviewed_at,
    rejected_reason = EXCLUDED.rejected_reason,
    updated_at = NOW();

-- Cập nhật đồng bộ các jobs hiện có trong DB
UPDATE jobs 
SET reviewed_by = CASE 
        WHEN status IN ('APPROVED', 'CLOSED') AND reviewed_by IS NULL THEN 'staff1@rikkeijobs.test'
        WHEN status = 'REJECTED' AND reviewed_by IS NULL THEN 'staff2@rikkeijobs.test'
        ELSE reviewed_by 
    END,
    reviewed_at = CASE 
        WHEN status IN ('APPROVED', 'CLOSED') AND reviewed_at IS NULL THEN COALESCE(created_at, NOW()) + interval '2 hours'
        WHEN status = 'REJECTED' AND reviewed_at IS NULL THEN COALESCE(created_at, NOW()) + interval '1 hour'
        ELSE reviewed_at 
    END,
    rejected_reason = CASE 
        WHEN status = 'REJECTED' AND rejected_reason IS NULL THEN 'Nội dung JD chưa đạt yêu cầu kiểm duyệt về mô tả công việc hoặc khung lương.'
        WHEN status != 'REJECTED' THEN NULL
        ELSE rejected_reason 
    END
WHERE status IN ('APPROVED', 'REJECTED', 'CLOSED') AND (reviewed_by IS NULL OR reviewed_at IS NULL OR (status = 'REJECTED' AND rejected_reason IS NULL));

-- =============================================================================
-- 5. ĐẢM BẢO KỸ NĂNG YÊU CẦU (JOB_SKILLS) CHO 120 JOBS
-- =============================================================================
ON CONFLICT (job_id, skill_id) DO NOTHING;

-- =============================================================================
-- 6. SEED DỮ LIỆU BẢNG COMPANY_ACTIONS
-- Các hành động: APPROVE_JD, REJECT_JD, LOCK, UNLOCK theo số lượng tương ứng
-- =============================================================================
ON CONFLICT (id) DO UPDATE SET
    action = EXCLUDED.action,
    reason = EXCLUDED.reason,
    staff_id = EXCLUDED.staff_id,
    created_at = EXCLUDED.created_at;

-- Đồng bộ tự động các hành động kiểm duyệt JD cho các job chưa có log trong company_actions
SELECT 
    gen_random_uuid(),
    j.company_id,
    'APPROVE_JD',
    j.id,
    'Phê duyệt tin tuyển dụng đạt chuẩn chất lượng và chính sách tuyển dụng.',
    COALESCE(j.reviewed_by, 'staff1@rikkeijobs.test'),
    COALESCE(j.reviewed_at, j.updated_at, j.created_at)
FROM jobs j
WHERE j.status IN ('APPROVED', 'CLOSED')
AND NOT EXISTS (
    SELECT 1 FROM company_actions ca WHERE ca.target_id = j.id AND ca.action = 'APPROVE_JD'
);

SELECT 
    gen_random_uuid(),
    j.company_id,
    'REJECT_JD',
    j.id,
    COALESCE(j.rejected_reason, 'Yêu cầu kỹ năng và quyền lợi chưa rõ ràng hoặc mức lương chưa phù hợp quy chuẩn thị trường'),
    COALESCE(j.reviewed_by, 'staff2@rikkeijobs.test'),
    COALESCE(j.reviewed_at, j.updated_at, j.created_at)
FROM jobs j
WHERE j.status = 'REJECTED'
AND NOT EXISTS (
    SELECT 1 FROM company_actions ca WHERE ca.target_id = j.id AND ca.action = 'REJECT_JD'
);
